def img(path,maxwidth=510,maxheight=500):
    w,hh=PILImage.open(path).size; scale=min(maxwidth/w,maxheight/hh);return Image(str(path),width=w*scale,height=hh*scale,hAlign='LEFT')
def footer(label):
    def f(c,doc):
        c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#607180'));c.drawString(42,25,label+' | Workbook files and independently checked calculations');c.drawRightString(553,25,str(doc.page))
    return f

def build(path,story,label):
    d=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=40,bottomMargin=44,title=label+' - Thai report',author='BI Workshop')
    d.build(story,onFirstPage=footer(label),onLaterPages=footer(label))
    pdf=pdfium.PdfDocument(str(path));q=path.parent/'qa/pdf';q.mkdir(parents=True,exist_ok=True);thumbs=[]
    for i,page in enumerate(pdf):
        im=page.render(scale=1.6).to_pil().convert('RGB');im.save(q/f'page-{i+1:02}.png');th=im.copy();th.thumbnail((330,480));canvas=PILImage.new('RGB',(350,515),'white');canvas.paste(th,((350-th.width)//2,20));from PIL import ImageDraw;ImageDraw.Draw(canvas).text((12,495),f'Page {i+1}',fill='black');thumbs.append(canvas)
    columns=2;rows=math.ceil(len(thumbs)/columns);sheet=PILImage.new('RGB',(columns*350,rows*515),'#dbe3ec')
    for i,t in enumerate(thumbs):sheet.paste(t,((i%columns)*350,(i//columns)*515))
    sheet.save(q/'contact-sheet.png');return len(pdf)

